import "server-only";

import { readFileSync } from "node:fs";
import { join } from "node:path";

export type BuildInfo = {
  version: string;
  commit: string;
  builtAt: string;
  environment: "development" | "preview" | "production" | string;
  deploymentId?: string;
};

const fallback: BuildInfo = {
  version: "0.1.0",
  commit: "unknown",
  builtAt: new Date(0).toISOString(),
  environment: "development",
  deploymentId: "dev-live",
};

/** Reads the immutable build manifest generated by the prebuild step. */
export function readBuildInfo(): BuildInfo {
  try {
    const manifest = JSON.parse(readFileSync(join(process.cwd(), "public", "build-info.json"), "utf8")) as Partial<BuildInfo>;
    if (!manifest.version || !manifest.commit || !manifest.builtAt || !manifest.environment) return fallback;
    return manifest as BuildInfo;
  } catch {
    return fallback;
  }
}
